<?php $title='Projetos GDA'; ?>
<section class="page-head"><div><h1>Projetos GDA</h1><p>Produtos e módulos oferecidos pela GDA.</p></div><a class="btn primary" href="<?=e(base_url('projetos/anexar'))?>">Anexar módulo</a></section>
<?php if(!$projects):?><section class="panel"><div class="empty">Nenhum projeto cadastrado.</div></section><?php else:?><div class="module-grid"><?php foreach($projects as$p):$integrated=($p['integration_status']??'')==='integrado';?>
<article class="module-card"><div class="module-icon" aria-hidden="true"><?=$p['icon']==='wallet'?'▣':'◆'?></div><div class="module-card-head"><div><h2><?=e($p['name'])?></h2><small><?=e($p['full_name']?:$p['code'])?></small></div><span class="badge <?=$integrated?'active':'deploying'?>"><?=$integrated?'Integrado':(!empty($p['connection_status'])?'Anexado · Não integrado':project_status_label($p['status']))?></span></div><p><?=e($p['description'])?></p><div class="module-meta"><span>v<?=e($p['version'])?></span><span><?=(int)$p['client_count']?> cliente(s)</span></div><div class="module-actions"><a class="btn" href="<?=e(base_url('projetos/'.$p['id']))?>">Ver detalhes</a><?php if(!empty($p['connection_status'])):?><form method="post" action="<?=e(base_url('projetos/'.$p['id'].'/administrar'))?>"><?=csrf_field()?><button class="btn primary" type="submit">Administrar</button></form><?php endif;?></div></article>
<?php endforeach;?></div><?php endif;?>
